package com.claudiodekker.wyrmscraiggoathunting;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Tracks which goats are spoken for, keeping a hard distinction between the two ways we
 * come to believe that.
 * <p>
 * A capture <em>you</em> started is a fact: we saw the click. Those are the only ones
 * counted against the pit's remaining slots, because spending a slot on a guess is what
 * makes the pit go reserved too early and switches highlighting off entirely.
 * <p>
 * A capture inferred from a goat's spot anim is a guess. Guesses are good enough to stop
 * recommending a goat, and nothing worse happens if one is wrong, so they only ever hide.
 * <p>
 * Every claim lapses after {@link GoatPit#BUSY_TIMEOUT_TICKS}, so nothing can get stuck.
 */
public final class CaptureLedger
{
	/** Goats you telegrabbed or prodded, mapped to the tick their claim lapses. */
	private final Map<Integer, Integer> mine = new HashMap<>();

	/** Goats someone else appears to have, mapped to the tick their claim lapses. */
	private final Map<Integer, Integer> theirs = new HashMap<>();

	/** Records or refreshes a capture you started. */
	public void mine(int npcIndex, int tick)
	{
		mine.put(npcIndex, tick + GoatPit.BUSY_TIMEOUT_TICKS);
	}

	/** Records or refreshes a capture someone else appears to have started. */
	public void theirs(int npcIndex, int tick)
	{
		theirs.put(npcIndex, tick + GoatPit.BUSY_TIMEOUT_TICKS);
	}

	/**
	 * The game told us this goat is already being moved by someone else, so the slot was
	 * never ours. Stops counting it while still keeping it out of the recommendations.
	 */
	public void handOff(int npcIndex, int tick)
	{
		mine.remove(npcIndex);
		theirs(npcIndex, tick);
	}

	/** The goat is gone, most likely into the pit, so no claim on it means anything now. */
	public void forget(int npcIndex)
	{
		mine.remove(npcIndex);
		theirs.remove(npcIndex);
	}

	public void expire(int tick)
	{
		mine.values().removeIf(lapsesAt -> lapsesAt <= tick);
		theirs.values().removeIf(lapsesAt -> lapsesAt <= tick);
	}

	public void clear()
	{
		mine.clear();
		theirs.clear();
	}

	/** True when anyone, you included, appears to be capturing this goat. */
	public boolean isClaimed(int npcIndex)
	{
		return mine.containsKey(npcIndex) || theirs.containsKey(npcIndex);
	}

	public boolean isMine(int npcIndex)
	{
		return mine.containsKey(npcIndex);
	}

	/** Goats you are capturing right now, which will take pit slots the varbit cannot see yet. */
	public int inFlight()
	{
		return mine.size();
	}

	/** Every goat not worth recommending, whoever is taking it. */
	public Set<Integer> hidden()
	{
		Set<Integer> hidden = new HashSet<>(mine.keySet());
		hidden.addAll(theirs.keySet());
		return Collections.unmodifiableSet(hidden);
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import net.runelite.api.coords.WorldPoint;

/**
 * The triangle of tiles you can capture from, opening away from the pit on the side
 * opposite to where you stand.
 * <p>
 * The cone is anchored to the pit, not to you: a goat is pulled towards the pit's centre,
 * so the cone's centre line always runs through that centre tile and its apex sits on the
 * pit's far edge. Where you stand within a side only picks the direction the cone faces.
 * That makes the shape identical for all three tiles of a side.
 * <p>
 * A tile qualifies when it is {@code d} tiles past the pit's edge ({@code d >= 1}) and no
 * more than {@code d * spread} tiles off the centre line. East and west share one spread,
 * north and south share another, so the pen's rectangular shape can be matched by fanning
 * the north/south cones out faster. Range is measured from the player, because that is
 * where Telekinetic Grab is cast from.
 */
public final class CaptureZone
{
	private final WorldPoint pit;
	private final PitSide side;
	private final WorldPoint standingTile;
	private final int eastWestSpread;
	private final int northSouthSpread;
	private final int maxRange;
	private final ConeWidth width;

	private List<WorldPoint> tiles;

	/** The zone for a player stood on {@code standingTile}, using the pit's own geometry. */
	public static CaptureZone forSide(PitSide side, WorldPoint standingTile, ConeWidth width)
	{
		return new CaptureZone(
			GoatPit.PIT_LOCATION,
			side,
			standingTile,
			GoatPit.SPREAD_EAST_WEST,
			GoatPit.SPREAD_NORTH_SOUTH,
			GoatPit.TELEGRAB_RANGE,
			width);
	}

	public CaptureZone(WorldPoint pit, PitSide side, WorldPoint standingTile, int eastWestSpread, int northSouthSpread, int maxRange)
	{
		this(pit, side, standingTile, eastWestSpread, northSouthSpread, maxRange, ConeWidth.QUARTER);
	}

	public CaptureZone(WorldPoint pit, PitSide side, WorldPoint standingTile, int eastWestSpread, int northSouthSpread, int maxRange, ConeWidth width)
	{
		this.pit = pit;
		this.side = side;
		this.standingTile = standingTile;
		this.eastWestSpread = eastWestSpread;
		this.northSouthSpread = northSouthSpread;
		this.maxRange = maxRange;
		this.width = width;
	}

	public WorldPoint pit()
	{
		return pit;
	}

	/**
	 * Whether the zone already describes this position, so the caller can keep it rather
	 * than build an identical one and throw away the tiles it has already enumerated.
	 */
	public boolean matches(PitSide side, WorldPoint standingTile, ConeWidth width)
	{
		return this.side == side
			&& this.width == width
			&& Objects.equals(this.standingTile, standingTile);
	}

	private int spread()
	{
		return side.isNorthSouthAxis() ? northSouthSpread : eastWestSpread;
	}

	public boolean contains(WorldPoint target)
	{
		if (target == null || target.getPlane() != pit.getPlane())
		{
			return false;
		}

		int dx = target.getX() - pit.getX();
		int dy = target.getY() - pit.getY();

		// Distance is counted from the pit's edge, so the first row beyond the pit is 1.
		int distance = (dx * side.aimDx() + dy * side.aimDy()) - GoatPit.PIT_RADIUS;
		if (distance < 1)
		{
			return false;
		}

		// Widened to the whole half, the only thing bounding it sideways is your range.
		if (width == ConeWidth.QUARTER)
		{
			int offset = Math.abs(dx * side.aimDy() - dy * side.aimDx());
			if (offset > distance * spread())
			{
				return false;
			}
		}

		return standingTile == null || standingTile.distanceTo2D(target) <= maxRange;
	}

	/**
	 * Every tile in the zone, for drawing the cone on the ground.
	 * <p>
	 * Enumerated once and kept, because the overlay asks for this on every frame while the
	 * zone itself only changes when you move or a neighbour arrives.
	 */
	public List<WorldPoint> tiles()
	{
		if (tiles == null)
		{
			tiles = Collections.unmodifiableList(enumerateTiles());
		}

		return tiles;
	}

	private List<WorldPoint> enumerateTiles()
	{
		List<WorldPoint> found = new ArrayList<>();

		int aimDx = side.aimDx();
		int aimDy = side.aimDy();

		// Perpendicular to the aim direction, so offsets sweep across the cone's width.
		int perpDx = aimDy;
		int perpDy = -aimDx;

		for (int distance = 1; distance <= maxRange; distance++)
		{
			int reach = distance + GoatPit.PIT_RADIUS;

			// Widened, nothing bounds the offset but your range, and Chebyshev distance
			// means an offset can never usefully exceed it.
			int halfWidth = width == ConeWidth.QUARTER ? distance * spread() : maxRange;

			for (int offset = -halfWidth; offset <= halfWidth; offset++)
			{
				WorldPoint tile = new WorldPoint(
					pit.getX() + aimDx * reach + perpDx * offset,
					pit.getY() + aimDy * reach + perpDy * offset,
					pit.getPlane());

				// Re-check rather than trust the loop bounds, so enumeration can never
				// disagree with contains() about the range cap.
				if (contains(tile))
				{
					found.add(tile);
				}
			}
		}

		return found;
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import java.util.Collection;

/**
 * How much of the far side you should be aiming at, which depends on who else is working
 * the pit.
 * <p>
 * Only a player perpendicular to you competes for the same goats. Someone opposite is
 * aiming back across the pit at the half you are standing in, so they never take anything
 * you would have taken — no reason to stay narrow for them.
 */
public enum ConeWidth
{
	/** The 45-degree-ish cone. Leaves room for the players to your left and right. */
	QUARTER,

	/** The entire opposite half, split through the pit. Nobody is competing for it. */
	HALF;

	public static ConeWidth forNeighbours(PitSide mine, Collection<PitSide> occupiedByOthers)
	{
		for (PitSide other : occupiedByOthers)
		{
			if (mine.isPerpendicularTo(other))
			{
				return QUARTER;
			}
		}

		return HALF;
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import net.runelite.api.coords.WorldPoint;

/**
 * A goat reduced to what targeting actually needs: its NPC index, where it stands, and
 * whether you have a clear shot at it. Keeps the selection logic free of any client types
 * — line of sight is resolved against the scene by the plugin and passed in as a fact.
 */
public final class GoatCandidate
{
	private final int index;
	private final WorldPoint location;
	private final boolean hasLineOfSight;

	public GoatCandidate(int index, WorldPoint location, boolean hasLineOfSight)
	{
		this.index = index;
		this.location = location;
		this.hasLineOfSight = hasLineOfSight;
	}

	public int index()
	{
		return index;
	}

	public WorldPoint location()
	{
		return location;
	}

	/** False when something is in the way, which would make you run around to reach it. */
	public boolean hasLineOfSight()
	{
		return hasLineOfSight;
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import net.runelite.api.coords.WorldPoint;

/**
 * Fixed world data for the Wyrmscraig goat pit.
 * <p>
 * These are hardcoded rather than referenced through {@code net.runelite.api.gameval}
 * because the constants only landed on RuneLite master in "Update GameVals to
 * 2026-07-29-rev239" and are not in any published client artifact yet. Once a release
 * ships that contains them, these can be swapped for the named constants noted below.
 */
public final class GoatPit
{
	/** {@code NpcID.GOAT_PIT_GOAT} */
	public static final int GOAT_NPC_ID = 16298;

	/** The pit game object. Its id is stable across fill states. */
	public static final int PIT_OBJECT_ID = 62343;

	/** Centre of the 3x3 pit, which covers 2571-2573 by 2194-2196. */
	public static final WorldPoint PIT_LOCATION = new WorldPoint(2572, 2195, 0);

	/** Tiles from the pit's centre to its edge. The pit is 3x3, so 1. */
	public static final int PIT_RADIUS = 1;

	/**
	 * Tiles from the pit's centre to a standing tile. You stand on the ring immediately
	 * around the pit, three tiles per side, so one further out than the edge.
	 */
	public static final int STANDING_DISTANCE = PIT_RADIUS + 1;

	/** {@code VarbitID.GOAT_PIT_SPIKES} — 1 once the pit is lined, 0 while unlined or being cleared. */
	public static final int VARBIT_SPIKES = 15724;

	/** {@code VarbitID.GOAT_PIT_INPIT} — number of captured goats, 0 to {@link #MAX_IN_PIT}. */
	public static final int VARBIT_IN_PIT = 15725;

	/** {@code VarbitID.GOAT_PIT_STATE} — visual fill level, 0 when empty and unlined through 4 when full. */
	public static final int VARBIT_STATE = 15726;

	public static final int MAX_IN_PIT = 20;

	/** Telekinetic Grab's cast range, which bounds how far a capture can reach. */
	public static final int TELEGRAB_RANGE = 10;

	/**
	 * How fast the cone opens, in tiles of width per tile of distance past the pit's edge.
	 * Confirmed in game: east/west is a 45 degree cone, while north/south fans out twice as
	 * fast because the pen is shallower on that axis than it is wide.
	 */
	public static final int SPREAD_EAST_WEST = 1;
	public static final int SPREAD_NORTH_SOUTH = 2;

	/** Substring of "Someone else is currently moving that goat!". */
	public static final String CONTESTED_GOAT_MESSAGE = "currently moving that goat";

	/** Substring of "You don't think your current weapon would work as a cattleprod." */
	public static final String PROD_WRONG_WEAPON_MESSAGE = "would work as a cattleprod";

	/** Substring of "You should use a cattleprod if you want to prod the goats." */
	public static final String PROD_NO_WEAPON_MESSAGE = "use a cattleprod if you want to prod";

	/**
	 * The game refusing a prod outright, because you are not holding a cattleprod. Nothing
	 * happened to the goat, so any claim on it has to be dropped rather than handed off:
	 * it is not contested, it is simply still there.
	 * <p>
	 * Matched on the distinctive half of each sentence rather than on "cattleprod" alone,
	 * so a message about a successful prod cannot cancel a real capture.
	 */
	public static boolean isFailedProdMessage(String message)
	{
		return message != null
			&& (message.contains(PROD_WRONG_WEAPON_MESSAGE) || message.contains(PROD_NO_WEAPON_MESSAGE));
	}

	/**
	 * Spot anim a capture opens with, shown for several ticks. Watching for it catches
	 * other players' captures, which the chat message alone cannot.
	 */
	public static final int GRAPHIC_BEING_CAPTURED = 144;

	/** Animations the goat plays after the spot anim, while it is being pulled to the pit. */
	public static final int ANIMATION_BEING_PULLED = 14449;
	public static final int ANIMATION_BEING_PULLED_ALT = 5339;

	/**
	 * A capture is a sequence, not a single signal: spot anim 144 first, then one of the
	 * pull animations. Only the spot anim can open a capture. The pull animations merely
	 * sustain one that is already open, because goats play them for reasons that have
	 * nothing to do with this pit — treating them as an opening signal counted unrelated
	 * goats as in flight against an empty pit.
	 * <p>
	 * Note this reads the goat's <em>animation</em>, not its pose. An idle goat animates
	 * -1, so {@link #ANIMATION_BEING_PULLED_ALT} cannot collide with its resting pose even
	 * though the two share a number.
	 *
	 * @param hasCaptureGraphic whether spot anim {@link #GRAPHIC_BEING_CAPTURED} is active
	 * @param animation         the goat's current animation, -1 when idle
	 * @param alreadyClaimed    whether this goat already has a capture open
	 */
	public static boolean isBeingCaptured(boolean hasCaptureGraphic, int animation, boolean alreadyClaimed)
	{
		if (hasCaptureGraphic)
		{
			return true;
		}

		return alreadyClaimed && isPullAnimation(animation);
	}

	private static boolean isPullAnimation(int animation)
	{
		return animation == ANIMATION_BEING_PULLED || animation == ANIMATION_BEING_PULLED_ALT;
	}

	/**
	 * How long a goat stays marked busy after the last sign of a capture. Long enough to
	 * cover the walk to the pit, short enough that an aborted capture cannot hide a goat
	 * indefinitely.
	 */
	public static final int BUSY_TIMEOUT_TICKS = 10;

	/** Supply of spikes to take before the pit can be lined. */
	public static final int SPIKE_SUPPLY_OBJECT_ID = 62349;

	/** The spikes themselves, needed in the inventory to line the pit. */
	public static final int SPIKES_ITEM_ID = 34016;

	/** The goat's own menu option, which walks you over if left-clicked at a distance. */
	public static final String PROD_OPTION = "Prod";

	/**
	 * How close to the pit's centre you have to be for any of this to run. Wide enough to
	 * cover the pen and everything a capture can reach — you stand 2 tiles from the centre
	 * and Telekinetic Grab reaches {@link #TELEGRAB_RANGE} beyond that — while keeping the
	 * plugin inert everywhere else.
	 */
	public static final int ACTIVITY_RADIUS = 15;

	/**
	 * The activity gate. Everything else — tracking goats, resolving line of sight,
	 * touching menus — hangs off this, so the plugin costs nothing away from the pit.
	 */
	public static boolean isNearPit(WorldPoint location)
	{
		return location != null
			&& location.getPlane() == PIT_LOCATION.getPlane()
			&& location.distanceTo2D(PIT_LOCATION) <= ACTIVITY_RADIUS;
	}

	/** True when the two tiles touch, including diagonally. */
	public static boolean isAdjacent(WorldPoint a, WorldPoint b)
	{
		return a != null && b != null
			&& a.getPlane() == b.getPlane()
			&& a.distanceTo2D(b) <= 1;
	}

	private GoatPit()
	{
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/**
 * Decides which goats to outline: everything inside the cone, split by whether you have a
 * clear shot, with the nearest reachable one singled out as the one to grab next.
 */
public final class GoatTargeter
{
	private GoatTargeter()
	{
	}

	public static Selection select(Collection<GoatCandidate> goats, CaptureZone zone, Set<Integer> busy)
	{
		WorldPoint pit = zone.pit();

		Set<Integer> capturable = new HashSet<>();
		Set<Integer> blocked = new HashSet<>();
		Integer closestIndex = null;
		int closestDistance = Integer.MAX_VALUE;

		for (GoatCandidate goat : goats)
		{
			if (busy.contains(goat.index()) || !zone.contains(goat.location()))
			{
				continue;
			}

			// A goat behind cover is still worth showing, but telegrabbing it would make
			// you run around, so it never becomes the recommendation.
			if (!goat.hasLineOfSight())
			{
				blocked.add(goat.index());
				continue;
			}

			capturable.add(goat.index());

			int distance = goat.location().distanceTo2D(pit);

			// Ties break on the lower index so the highlight stays put between frames
			// instead of flickering between two equidistant goats.
			boolean better = closestIndex == null
				|| distance < closestDistance
				|| (distance == closestDistance && goat.index() < closestIndex);

			if (better)
			{
				closestDistance = distance;
				closestIndex = goat.index();
			}
		}

		return new Selection(capturable, blocked, closestIndex);
	}

	public static final class Selection
	{
		private final Set<Integer> capturable;
		private final Set<Integer> blocked;
		private final Integer closestIndex;

		private Selection(Set<Integer> capturable, Set<Integer> blocked, Integer closestIndex)
		{
			this.capturable = capturable;
			this.blocked = blocked;
			this.closestIndex = closestIndex;
		}

		public static Selection empty()
		{
			return new Selection(Collections.emptySet(), Collections.emptySet(), null);
		}

		public Set<Integer> capturable()
		{
			return Collections.unmodifiableSet(capturable);
		}

		public Set<Integer> blocked()
		{
			return Collections.unmodifiableSet(blocked);
		}

		public Integer closestIndex()
		{
			return closestIndex;
		}

		/** True when nothing is outlined, so the overlay can skip walking the scene at all. */
		public boolean isEmpty()
		{
			return capturable.isEmpty() && blocked.isEmpty();
		}

		public boolean isCapturable(int npcIndex)
		{
			return capturable.contains(npcIndex);
		}

		public boolean isBlocked(int npcIndex)
		{
			return blocked.contains(npcIndex);
		}

		public boolean isClosest(int npcIndex)
		{
			return closestIndex != null && closestIndex == npcIndex;
		}
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

/**
 * How full the pit is, as fractions for the bar drawn over it.
 * <p>
 * Split into what has landed and what is on its way, so the bar can show the pit filling
 * up before the goats arrive without making you read "16+3/20" and do the sum yourself.
 */
public final class PitFill
{
	private final double landed;
	private final double pending;

	private PitFill(double landed, double pending)
	{
		this.landed = landed;
		this.pending = pending;
	}

	public static PitFill of(int inPit, int inFlight)
	{
		double landed = clamp((double) inPit / GoatPit.MAX_IN_PIT, 0.0, 1.0);

		// Whatever is in flight can only fill the room that is actually left, so an
		// overshoot tops the bar out instead of running past the end of it.
		double pending = clamp((double) inFlight / GoatPit.MAX_IN_PIT, 0.0, 1.0 - landed);

		return new PitFill(landed, pending);
	}

	private static double clamp(double value, double min, double max)
	{
		return Math.max(min, Math.min(max, value));
	}

	/** Fraction of the pit taken by goats that have already fallen in. */
	public double landed()
	{
		return landed;
	}

	/** Fraction taken by goats being lured, which have not landed yet. */
	public double pending()
	{
		return pending;
	}

	public double total()
	{
		return landed + pending;
	}

	public boolean isEmpty()
	{
		return total() <= 0.0;
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import net.runelite.api.coords.WorldPoint;

/**
 * Which side of the 3x3 pit you are standing on. Each side has three tiles; the four
 * diagonal corners belong to no side.
 * <p>
 * Standing north means capturing goats to the south: you telegrab across the pit and the
 * goat is pulled towards it.
 */
public enum PitSide
{
	NORTH(0, 1),
	SOUTH(0, -1),
	EAST(1, 0),
	WEST(-1, 0);

	/** Unit vector from the pit's centre towards this side. */
	private final int dirX;
	private final int dirY;

	PitSide(int dirX, int dirY)
	{
		this.dirX = dirX;
		this.dirY = dirY;
	}

	/**
	 * @return the side the player is standing on, or {@code null} if they are not on one
	 * of the twelve capture tiles.
	 */
	public static PitSide fromStandingTile(WorldPoint pit, WorldPoint player)
	{
		if (player == null || player.getPlane() != pit.getPlane())
		{
			return null;
		}

		int dx = player.getX() - pit.getX();
		int dy = player.getY() - pit.getY();

		for (PitSide side : values())
		{
			int along = dx * side.dirX + dy * side.dirY;
			int across = Math.abs(dx * side.dirY - dy * side.dirX);

			// One step beyond the pit's edge, and no further sideways than the pit is
			// wide. That admits three tiles per side and rejects the corners.
			if (along == GoatPit.STANDING_DISTANCE && across <= GoatPit.PIT_RADIUS)
			{
				return side;
			}
		}

		return null;
	}

	public int aimDx()
	{
		return -dirX;
	}

	public int aimDy()
	{
		return -dirY;
	}

	/** True when you are aiming along the north/south axis, which uses its own spread. */
	public boolean isNorthSouthAxis()
	{
		return dirX == 0;
	}

	/**
	 * True when the other side is at right angles to this one, which is exactly when the
	 * two compete for the same goats. Your own side and the opposite side both return
	 * false: the opposite player aims back across the pit at your half.
	 */
	public boolean isPerpendicularTo(PitSide other)
	{
		return isNorthSouthAxis() != other.isNorthSouthAxis();
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

/**
 * What the pit currently needs from you, derived from the three goat pit varbits plus the
 * goats already on their way into it.
 */
public enum PitStatus
{
	/** Empty and unlined. Line it with spikes to start. */
	NEEDS_SPIKES,

	/** Lined, with room to spare once the goats in flight land. Capturing works. */
	READY,

	/**
	 * Not full yet, but every remaining slot belongs to a goat already being lured.
	 * Casting now would burn runes on a goat with nowhere to land, so wait a moment.
	 */
	RESERVED,

	/** Twenty goats in. Clear it before capturing again. */
	FULL,

	/** Spikes removed while goats are still in it. No captures until it is cleared and re-lined. */
	CLEARING;

	/**
	 * @param spikes   {@code GOAT_PIT_SPIKES}
	 * @param state    {@code GOAT_PIT_STATE}
	 * @param inPit    {@code GOAT_PIT_INPIT}, goats that have already landed
	 * @param inFlight goats being lured towards the pit, which the varbit cannot know about
	 */
	public static PitStatus of(int spikes, int state, int inPit, int inFlight)
	{
		if (spikes == 0)
		{
			return state == 0 ? NEEDS_SPIKES : CLEARING;
		}

		if (inPit >= GoatPit.MAX_IN_PIT)
		{
			return FULL;
		}

		// The pit still has room, but not for anything new: those slots are spoken for.
		return inPit + inFlight >= GoatPit.MAX_IN_PIT ? RESERVED : READY;
	}

	public boolean canCapture()
	{
		return this == READY;
	}

	/**
	 * Whether the spikes are in, which is the only time the pit holds a fill level worth
	 * showing. Unlined it reads empty by definition, and while being cleared nothing can
	 * land in it.
	 */
	public boolean isLined()
	{
		return this == READY || this == RESERVED || this == FULL;
	}
}

