package com.claudiodekker.wyrmscraiggoathunting;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class WyrmscraigGoatHuntingOverlay extends Overlay
{
	private final Client client;
	private final WyrmscraigGoatHuntingPlugin plugin;
	private final WyrmscraigGoatHuntingConfig config;
	private final ModelOutlineRenderer outlineRenderer;

	private static final int BAR_WIDTH = 120;
	private static final int BAR_HEIGHT = 6;
	private static final int BAR_HEIGHT_ABOVE_PIT = 160;

	// Read like a health bar, so these are fixed rather than configurable: red is the room
	// left, green what has landed, orange what is still on its way. Blue replaces the green
	// while the pit is being emptied, so filling up and draining never look alike.
	private static final Color BAR_EMPTY = new Color(150, 25, 25);
	private static final Color BAR_LANDED = new Color(0, 200, 60);
	private static final Color BAR_PENDING = new Color(255, 150, 0);
	private static final Color BAR_DRAINING = new Color(0, 150, 255);
	private static final Color BAR_BORDER = new Color(0, 0, 0, 220);

	@Inject
	private WyrmscraigGoatHuntingOverlay(
		Client client,
		WyrmscraigGoatHuntingPlugin plugin,
		WyrmscraigGoatHuntingConfig config,
		ModelOutlineRenderer outlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlineRenderer = outlineRenderer;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GameObject pit = plugin.getPit();
		if (!plugin.isActive() || pit == null)
		{
			return null;
		}

		renderPit(graphics, pit);
		renderSpikeSupplies();
		renderCaptureZone(graphics);
		renderGoats();

		return null;
	}

	/** Only worth pointing at when the pit needs lining and you have nothing to line it with. */
	private void renderSpikeSupplies()
	{
		if (!plugin.needsSpikeSupply())
		{
			return;
		}

		for (GameObject supply : plugin.getSpikeSupplies())
		{
			outlineRenderer.drawOutline(supply, config.outlineWidth(), config.spikeSupplyColor(), config.outlineFeather());
		}
	}

	private void renderPit(Graphics2D graphics, GameObject pit)
	{
		outlineRenderer.drawOutline(pit, config.outlineWidth(), pitColor(), config.outlineFeather());

		if (config.showPitFillBar() && showsFillBar())
		{
			renderFillBar(graphics, pit);
		}
	}

	/**
	 * Shown while the pit is lined, and kept up afterwards for as long as it still holds
	 * goats, so emptying it drains the bar back to red rather than making it vanish. Once
	 * the pit is genuinely empty there is nothing left to say.
	 */
	private boolean showsFillBar()
	{
		return plugin.getStatus().isLined() || plugin.getInPit() > 0;
	}

	/**
	 * A bar rather than a count, so the pit's fullness reads at a glance without doing the
	 * arithmetic. Read like a health bar: the red background is the room left, green is
	 * what has landed, and orange past it is what is still on its way. That last segment
	 * is what makes it proactive — the bar fills up before the goats arrive.
	 * <p>
	 * While the pit is being emptied the fill turns blue and the orange disappears, since
	 * nothing can be on its way into a pit with its spikes out. Draining therefore never
	 * looks like filling.
	 * <p>
	 * Deliberately not tied to the pit's status colour, which stays on the outline.
	 */
	private void renderFillBar(Graphics2D graphics, GameObject pit)
	{
		Point anchor = pit.getCanvasLocation(BAR_HEIGHT_ABOVE_PIT);
		if (anchor == null)
		{
			return;
		}

		int x = anchor.getX() - BAR_WIDTH / 2;
		int y = anchor.getY();

		boolean draining = plugin.getStatus() == PitStatus.CLEARING;

		PitFill fill = PitFill.of(plugin.getInPit(), draining ? 0 : plugin.getInFlight());

		int landedWidth = (int) Math.round(fill.landed() * BAR_WIDTH);
		int pendingWidth = (int) Math.round(fill.total() * BAR_WIDTH) - landedWidth;

		graphics.setColor(BAR_EMPTY);
		graphics.fillRect(x, y, BAR_WIDTH, BAR_HEIGHT);

		graphics.setColor(draining ? BAR_DRAINING : BAR_LANDED);
		graphics.fillRect(x, y, landedWidth, BAR_HEIGHT);

		graphics.setColor(BAR_PENDING);
		graphics.fillRect(x + landedWidth, y, pendingWidth, BAR_HEIGHT);

		graphics.setColor(BAR_BORDER);
		graphics.drawRect(x, y, BAR_WIDTH, BAR_HEIGHT);
	}

	private Color pitColor()
	{
		switch (plugin.getStatus())
		{
			case NEEDS_SPIKES:
				// Red only when you cannot act on it yet; the supply turns green instead.
				return plugin.needsSpikeSupply() ? config.outOfSpikesColor() : config.actionNeededColor();
			case RESERVED:
				return config.reservedColor();
			case CLEARING:
				// A duller green while it empties itself. Without this the pit would look
				// identical before and after the clear finishes, and nothing would tell you
				// it is waiting to be re-lined.
				return config.clearingColor();
			case FULL:
				return config.actionNeededColor();
			case READY:
			default:
				return config.readyColor();
		}
	}

	/** Optional: paints the tiles you can capture from, for players who like seeing it. */
	private void renderCaptureZone(Graphics2D graphics)
	{
		CaptureZone zone = plugin.getZone();
		if (!config.showCaptureZone() || zone == null)
		{
			return;
		}

		for (WorldPoint tile : zone.tiles())
		{
			LocalPoint local = LocalPoint.fromWorld(client, tile);
			if (local == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, local);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, config.captureZoneColor());
			}
		}
	}

	private void renderGoats()
	{
		GoatTargeter.Selection selection = plugin.getSelection();
		if (selection.isEmpty())
		{
			return;
		}

		for (NPC npc : client.getNpcs())
		{
			if (npc.getId() != GoatPit.GOAT_NPC_ID)
			{
				continue;
			}

			Color color = null;
			if (selection.isClosest(npc.getIndex()))
			{
				color = config.closestColor();
			}
			else if (selection.isCapturable(npc.getIndex()))
			{
				color = config.capturableColor();
			}
			else if (selection.isBlocked(npc.getIndex()))
			{
				color = config.blockedColor();
			}

			if (color != null)
			{
				outlineRenderer.drawOutline(npc, config.outlineWidth(), color, config.outlineFeather());
			}
		}
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Wyrmscraig Goat Hunting",
	description = "Highlights goats, visualizes the goat pit's status, and prevents misclicks.",
	tags = {"wyrmscraig", "goat", "pit", "telegrab", "hunter"}
)
public class WyrmscraigGoatHuntingPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WyrmscraigGoatHuntingOverlay overlay;

	@Inject
	private WyrmscraigGoatHuntingConfig config;

	private GameObject pit;
	private final Map<WorldPoint, GameObject> spikeSupplies = new HashMap<>();

	private PitStatus status = PitStatus.NEEDS_SPIKES;
	private int inPit;

	/** Whether the plugin is doing anything at all: pit in scene and you near it. */
	private boolean active;

	/** True when the pit needs lining and you have no spikes to line it with. */
	private boolean needsSpikeSupply;

	/** Which of the twelve capture tiles you are on, or null if you are not on one. */
	private PitSide standingSide;

	/** Null unless you are stood on one of the twelve capture tiles with a usable pit. */
	private CaptureZone zone;

	private GoatTargeter.Selection selection = GoatTargeter.Selection.empty();

	/** Widens to the whole half when nobody is working the sides to your left or right. */
	private ConeWidth coneWidth = ConeWidth.QUARTER;

	private final CaptureLedger captures = new CaptureLedger();

	/** The goat we last acted on, so the contested message can be attributed. */
	private int lastTargetedGoat = -1;

	@Provides
	WyrmscraigGoatHuntingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WyrmscraigGoatHuntingConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::scanSceneForObjects);
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		reset();
	}

	private void reset()
	{
		active = false;
		standingSide = null;
		pit = null;
		spikeSupplies.clear();
		zone = null;
		coneWidth = ConeWidth.QUARTER;
		selection = GoatTargeter.Selection.empty();
		status = PitStatus.NEEDS_SPIKES;
		inPit = 0;
		needsSpikeSupply = false;
		captures.clear();
		lastTargetedGoat = -1;
	}

	/**
	 * The single gate everything hangs off. Away from the pit the plugin does no work at
	 * all: no goat scanning, no line of sight, no menu interference.
	 */
	private boolean nearPit()
	{
		Player local = client.getLocalPlayer();
		return local != null && GoatPit.isNearPit(local.getWorldLocation());
	}

	/**
	 * Objects only fire spawn events as the scene loads, so enabling the plugin while
	 * already standing at the pit would otherwise find nothing until the next reload.
	 */
	private void scanSceneForObjects()
	{
		WorldView worldView = client.getTopLevelWorldView();
		Tile[][][] tiles = worldView.getScene().getTiles();
		int plane = worldView.getPlane();

		for (Tile[] column : tiles[plane])
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}

				for (GameObject object : tile.getGameObjects())
				{
					if (object != null)
					{
						rememberObject(object);
					}
				}
			}
		}
	}

	private void rememberObject(GameObject object)
	{
		if (object.getId() == GoatPit.PIT_OBJECT_ID)
		{
			pit = object;
		}
		else if (object.getId() == GoatPit.SPIKE_SUPPLY_OBJECT_ID)
		{
			spikeSupplies.put(object.getWorldLocation(), object);
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		rememberObject(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject object = event.getGameObject();

		if (object.getId() == GoatPit.PIT_OBJECT_ID)
		{
			pit = null;
		}
		else if (object.getId() == GoatPit.SPIKE_SUPPLY_OBJECT_ID)
		{
			spikeSupplies.remove(object.getWorldLocation());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			reset();
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc.getId() != GoatPit.GOAT_NPC_ID)
		{
			return;
		}

		captures.forget(npc.getIndex());

		if (lastTargetedGoat == npc.getIndex())
		{
			lastTargetedGoat = -1;
		}
	}

	/**
	 * Both ways of taking a goat register a claim: casting Telekinetic Grab at range, and
	 * prodding one up close. This is the only signal we treat as fact, so it is the only
	 * one allowed to spend a pit slot.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		boolean capturing = event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_NPC
			|| GoatPit.PROD_OPTION.equals(event.getMenuOption());

		if (!capturing || !active)
		{
			return;
		}

		NPC npc = event.getMenuEntry().getNpc();
		if (npc != null && npc.getId() == GoatPit.GOAT_NPC_ID)
		{
			lastTargetedGoat = npc.getIndex();
			captures.mine(npc.getIndex(), client.getTickCount());
		}
	}

	/**
	 * Stops a stray left-click on a distant goat from walking you out of position. "Prod"
	 * is the goat's own option and is only safe up close; from a capture tile at range you
	 * want to be casting Telekinetic Grab.
	 * <p>
	 * This only applies while you are stood on one of the twelve capture tiles. Off them
	 * you are walking the pen on purpose, so Prod goes back to being the left-click.
	 * <p>
	 * This runs on {@link PostMenuSort}, the last hook before the menu is shown, and
	 * appends a no-op at the end of the array — which is the top of the menu, and so the
	 * left-click. Doing it here rather than on entry-add keeps placement deterministic:
	 * an injected entry added earlier is subject to the sort, and a {@code CANCEL}-typed
	 * one in particular sorts back down and lets "Walk here" take the left-click.
	 * <p>
	 * Prod itself is left alone, so it keeps its usual place on right-click.
	 */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		// Only while you are actually in position. Wandering the pen you want Prod back as
		// the left-click, since walking to a goat is then exactly what you meant.
		if (!config.blockDistantProd() || !active || standingSide == null)
		{
			return;
		}

		// With a spell selected the goat's own options give way to the cast entry, which
		// is exactly what we want left-clicked, so stay out of the way entirely.
		if (client.isWidgetSelected())
		{
			return;
		}

		Menu menu = client.getMenu();
		for (MenuEntry entry : menu.getMenuEntries())
		{
			if (isDistantGoatProd(entry))
			{
				menu.createMenuEntry(-1)
					.setOption("Nothing")
					.setType(MenuAction.RUNELITE)
					.onClick(ignored -> {
					});
				return;
			}
		}
	}

	private boolean isDistantGoatProd(MenuEntry entry)
	{
		if (!GoatPit.PROD_OPTION.equals(entry.getOption()))
		{
			return false;
		}

		NPC npc = entry.getNpc();
		if (npc == null || npc.getId() != GoatPit.GOAT_NPC_ID)
		{
			return false;
		}

		Player local = client.getLocalPlayer();
		return local != null && !GoatPit.isAdjacent(local.getWorldLocation(), npc.getWorldLocation());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (lastTargetedGoat < 0 || !active)
		{
			return;
		}

		String message = event.getMessage();

		if (message.contains(GoatPit.CONTESTED_GOAT_MESSAGE))
		{
			// The slot was never ours, so stop counting it while still keeping the goat
			// out of the recommendations.
			captures.handOff(lastTargetedGoat, client.getTickCount());
			lastTargetedGoat = -1;
		}
		else if (GoatPit.isFailedProdMessage(message))
		{
			// The prod was refused outright, so the goat is not going anywhere and should
			// go straight back to being a candidate.
			captures.forget(lastTargetedGoat);
			lastTargetedGoat = -1;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		active = pit != null && nearPit();

		if (!active)
		{
			standDown();
			return;
		}

		List<NPC> goats = goatsInScene();

		trackBusyGoats(goats);
		updateStatus();
		updateTargeting(goats);
	}

	/** Drops everything derived from being at the pit, so nothing stays drawn or counted. */
	private void standDown()
	{
		standingSide = null;
		zone = null;
		coneWidth = ConeWidth.QUARTER;
		needsSpikeSupply = false;
		selection = GoatTargeter.Selection.empty();
	}

	private void updateStatus()
	{
		inPit = client.getVarbitValue(GoatPit.VARBIT_IN_PIT);

		// Goats already being lured will take slots the varbit does not know about yet.
		// Counting them stops us burning runes on a goat that would land in a full pit.
		status = PitStatus.of(
			client.getVarbitValue(GoatPit.VARBIT_SPIKES),
			client.getVarbitValue(GoatPit.VARBIT_STATE),
			inPit,
			captures.inFlight());

		needsSpikeSupply = status == PitStatus.NEEDS_SPIKES && !holdingSpikes();
	}

	private void updateTargeting(Collection<NPC> goats)
	{
		Player local = client.getLocalPlayer();
		WorldPoint standing = local == null ? null : local.getWorldLocation();
		standingSide = standing == null ? null : PitSide.fromStandingTile(GoatPit.PIT_LOCATION, standing);

		if (!status.canCapture() || standingSide == null)
		{
			zone = null;
			selection = GoatTargeter.Selection.empty();
			return;
		}

		coneWidth = ConeWidth.forNeighbours(standingSide, sidesHeldByOthers(local));

		// Kept whenever it would come out identical, so the tiles it enumerates for the
		// overlay survive rather than being rebuilt every tick.
		if (zone == null || !zone.matches(standingSide, standing, coneWidth))
		{
			zone = CaptureZone.forSide(standingSide, standing, coneWidth);
		}

		selection = GoatTargeter.select(candidates(goats, standing), zone, captures.hidden());
	}

	/**
	 * Which of the four sides other players are working, judged the same way we judge our
	 * own: standing squarely on one of that side's three tiles.
	 */
	private Set<PitSide> sidesHeldByOthers(Player local)
	{
		Set<PitSide> sides = EnumSet.noneOf(PitSide.class);

		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player == null || player == local)
			{
				continue;
			}

			PitSide side = PitSide.fromStandingTile(GoatPit.PIT_LOCATION, player.getWorldLocation());
			if (side != null)
			{
				sides.add(side);
			}
		}

		return sides;
	}

	private boolean holdingSpikes()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		return inventory != null && inventory.contains(GoatPit.SPIKES_ITEM_ID);
	}

	private List<NPC> goatsInScene()
	{
		List<NPC> goats = new ArrayList<>();

		for (NPC npc : client.getNpcs())
		{
			if (npc.getId() == GoatPit.GOAT_NPC_ID)
			{
				goats.add(npc);
			}
		}

		return goats;
	}

	/**
	 * Sustains claims from what the goats are doing. A goat we already know is ours has
	 * its own claim refreshed; anything else is someone else's and only ever hides, never
	 * counts, because this signal is inference rather than fact.
	 */
	private void trackBusyGoats(Collection<NPC> goats)
	{
		int tick = client.getTickCount();

		for (NPC goat : goats)
		{
			int index = goat.getIndex();
			boolean hasCaptureGraphic = goat.hasSpotAnim(GoatPit.GRAPHIC_BEING_CAPTURED);

			if (!GoatPit.isBeingCaptured(hasCaptureGraphic, goat.getAnimation(), captures.isClaimed(index)))
			{
				continue;
			}

			if (captures.isMine(index))
			{
				captures.mine(index, tick);
			}
			else
			{
				captures.theirs(index, tick);
			}
		}

		captures.expire(tick);
	}

	private List<GoatCandidate> candidates(Collection<NPC> goats, WorldPoint standing)
	{
		List<GoatCandidate> candidates = new ArrayList<>();

		WorldView worldView = client.getTopLevelWorldView();
		WorldArea from = standing.toWorldArea();

		for (NPC goat : goats)
		{
			WorldPoint location = goat.getWorldLocation();
			candidates.add(new GoatCandidate(goat.getIndex(), location, from.hasLineOfSightTo(worldView, location)));
		}

		return candidates;
	}

	/** False whenever the overlay should draw nothing and the plugin should cost nothing. */
	boolean isActive()
	{
		return active;
	}

	GameObject getPit()
	{
		return pit;
	}

	Collection<GameObject> getSpikeSupplies()
	{
		return spikeSupplies.values();
	}

	boolean needsSpikeSupply()
	{
		return needsSpikeSupply;
	}

	PitStatus getStatus()
	{
		return status;
	}

	int getInPit()
	{
		return inPit;
	}

	/** Goats you are capturing right now, which will land in the pit shortly. */
	int getInFlight()
	{
		return captures.inFlight();
	}

	CaptureZone getZone()
	{
		return zone;
	}

	GoatTargeter.Selection getSelection()
	{
		return selection;
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Only captures you started count against the pit. Ones inferred from a goat's spot anim
 * are guesses: good enough to stop recommending that goat, not good enough to spend the
 * pit's remaining slots on.
 */
public class CaptureLedgerTest
{
	private static final int TIMEOUT = GoatPit.BUSY_TIMEOUT_TICKS;

	private CaptureLedger ledger;

	@Before
	public void setUp()
	{
		ledger = new CaptureLedger();
	}

	// --- what counts against the pit ---

	@Test
	public void nothingIsInFlightToStart()
	{
		assertEquals(0, ledger.inFlight());
		assertTrue(ledger.hidden().isEmpty());
	}

	@Test
	public void yourOwnCaptureCountsAgainstThePit()
	{
		ledger.mine(5, 100);

		assertEquals(1, ledger.inFlight());
		assertTrue(ledger.isClaimed(5));
	}

	@Test
	public void someoneElsesCaptureNeverCountsAgainstThePit()
	{
		ledger.theirs(7, 100);
		ledger.theirs(8, 100);
		ledger.theirs(9, 100);

		assertEquals("other players' goats must not consume our slots", 0, ledger.inFlight());
	}

	@Test
	public void someoneElsesCaptureStillHidesTheGoat()
	{
		ledger.theirs(7, 100);

		assertTrue(ledger.hidden().contains(7));
		assertTrue(ledger.isClaimed(7));
	}

	@Test
	public void bothKindsAreHidden()
	{
		ledger.mine(5, 100);
		ledger.theirs(7, 100);

		assertEquals(new HashSet<>(Arrays.asList(5, 7)), ledger.hidden());
		assertEquals(1, ledger.inFlight());
	}

	@Test
	public void repeatingYourOwnCaptureDoesNotDoubleCount()
	{
		ledger.mine(5, 100);
		ledger.mine(5, 101);
		ledger.mine(5, 102);

		assertEquals(1, ledger.inFlight());
	}

	// --- several goats can be on their way at once ---

	@Test
	public void capturingASecondGoatDoesNotReplaceTheFirst()
	{
		ledger.mine(5, 100);
		ledger.mine(7, 101);

		assertEquals("both are walking to the pit", 2, ledger.inFlight());
		assertTrue(ledger.isMine(5));
		assertTrue(ledger.isMine(7));
	}

	@Test
	public void everyConcurrentCaptureReservesItsOwnSlot()
	{
		ledger.mine(5, 100);
		ledger.mine(7, 100);
		ledger.mine(9, 101);
		ledger.mine(11, 102);

		assertEquals(4, ledger.inFlight());
		assertEquals(new HashSet<>(Arrays.asList(5, 7, 9, 11)), ledger.hidden());
	}

	@Test
	public void concurrentCapturesLapseIndependently()
	{
		ledger.mine(5, 100);
		ledger.mine(7, 106);

		ledger.expire(100 + TIMEOUT);

		assertFalse("the older claim has lapsed", ledger.isMine(5));
		assertTrue("the newer one has not", ledger.isMine(7));
		assertEquals(1, ledger.inFlight());
	}

	@Test
	public void oneGoatLandingLeavesTheOthersCounted()
	{
		ledger.mine(5, 100);
		ledger.mine(7, 100);
		ledger.mine(9, 100);

		ledger.forget(7);

		assertEquals(2, ledger.inFlight());
		assertTrue(ledger.isMine(5));
		assertTrue(ledger.isMine(9));
	}

	@Test
	public void losingOneGoatToSomeoneElseLeavesTheOthersCounted()
	{
		ledger.mine(5, 100);
		ledger.mine(7, 100);

		ledger.handOff(7, 101);

		assertEquals("only the contested one stops counting", 1, ledger.inFlight());
		assertTrue(ledger.isMine(5));
		assertFalse(ledger.isMine(7));
	}

	// --- expiry ---

	@Test
	public void aClaimSurvivesUntilItsTimeout()
	{
		ledger.mine(5, 100);

		ledger.expire(100 + TIMEOUT - 1);

		assertEquals(1, ledger.inFlight());
	}

	@Test
	public void aClaimLapsesOnceTheTimeoutPasses()
	{
		ledger.mine(5, 100);

		ledger.expire(100 + TIMEOUT);

		assertEquals(0, ledger.inFlight());
		assertFalse(ledger.isClaimed(5));
	}

	@Test
	public void refreshingAClaimPushesItsTimeoutOut()
	{
		ledger.mine(5, 100);
		ledger.mine(5, 105);

		ledger.expire(100 + TIMEOUT);

		assertEquals("still being pulled, so it should not have lapsed", 1, ledger.inFlight());
	}

	@Test
	public void expiryAppliesToOtherPlayersClaimsToo()
	{
		ledger.theirs(7, 100);

		ledger.expire(100 + TIMEOUT);

		assertFalse(ledger.isClaimed(7));
		assertTrue(ledger.hidden().isEmpty());
	}

	// --- the goat landing in the pit ---

	@Test
	public void forgettingAGoatDropsBothKindsOfClaim()
	{
		ledger.mine(5, 100);
		ledger.theirs(7, 100);

		ledger.forget(5);
		ledger.forget(7);

		assertEquals(0, ledger.inFlight());
		assertTrue(ledger.hidden().isEmpty());
	}

	@Test
	public void forgettingAnUnknownGoatIsHarmless()
	{
		ledger.forget(1234);

		assertEquals(0, ledger.inFlight());
	}

	// --- losing a goat to someone else ---

	@Test
	public void handingOffMovesTheGoatOutOfYourCount()
	{
		// You cast, then the game says someone else is already moving it.
		ledger.mine(5, 100);
		ledger.handOff(5, 101);

		assertEquals("the slot was never yours to reserve", 0, ledger.inFlight());
		assertTrue("but the goat is still not worth recommending", ledger.hidden().contains(5));
	}

	@Test
	public void handingOffAGoatYouNeverClaimedStillHidesIt()
	{
		ledger.handOff(9, 100);

		assertEquals(0, ledger.inFlight());
		assertTrue(ledger.hidden().contains(9));
	}

	@Test
	public void aHandedOffClaimStillLapses()
	{
		ledger.mine(5, 100);
		ledger.handOff(5, 101);

		ledger.expire(101 + TIMEOUT);

		assertTrue(ledger.hidden().isEmpty());
	}

	// --- resetting ---

	@Test
	public void clearingDropsEverything()
	{
		ledger.mine(5, 100);
		ledger.theirs(7, 100);

		ledger.clear();

		assertEquals(0, ledger.inFlight());
		assertTrue(ledger.hidden().isEmpty());
	}

	@Test
	public void hiddenIsNotModifiableFromOutside()
	{
		ledger.mine(5, 100);

		try
		{
			ledger.hidden().add(99);
		}
		catch (UnsupportedOperationException expected)
		{
			// good
		}

		assertEquals(Collections.singleton(5), ledger.hidden());
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import java.util.HashSet;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The cone starts at the 3x3 pit's far edge and stays centred on the pit's middle line,
 * whichever of a side's three tiles you stand on. Distance {@code d} counts tiles past
 * that edge, so the tile immediately beyond the pit is d = 1.
 */
public class CaptureZoneTest
{
	private static final WorldPoint PIT = new WorldPoint(2572, 2195, 0);

	private static final int EAST_WEST_SPREAD = 1;
	private static final int NORTH_SOUTH_SPREAD = 2;
	private static final int GENEROUS_RANGE = 40;

	private static WorldPoint tile(int x, int y)
	{
		return new WorldPoint(x, y, 0);
	}

	private static CaptureZone zone(PitSide side, WorldPoint standing)
	{
		return new CaptureZone(PIT, side, standing, EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, GENEROUS_RANGE);
	}

	// --- the cone starts at the pit's edge, not its centre ---

	@Test
	public void noTileOnThePitFootprintIsCapturable()
	{
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));

		for (int x = 2571; x <= 2573; x++)
		{
			for (int y = 2194; y <= 2196; y++)
			{
				assertFalse("pit tile should not be capturable: " + x + "," + y, zone.contains(tile(x, y)));
			}
		}
	}

	@Test
	public void theTileJustPastThePitIsDistanceOne()
	{
		// Standing east, aiming west: the pit's west edge is x=2571, so x=2570 is d=1
		// and with a spread of 1 that admits exactly the pit's own three-wide face.
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));

		assertTrue(zone.contains(tile(2570, 2194)));
		assertTrue(zone.contains(tile(2570, 2195)));
		assertTrue(zone.contains(tile(2570, 2196)));
		assertFalse(zone.contains(tile(2570, 2197)));
		assertFalse(zone.contains(tile(2570, 2193)));
	}

	@Test
	public void theConeWidensByTheSpreadPerTilePastTheEdge()
	{
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));

		// d = 2 at x = 2569, so the offset may reach 2.
		assertTrue(zone.contains(tile(2569, 2197)));
		assertTrue(zone.contains(tile(2569, 2193)));
		assertFalse(zone.contains(tile(2569, 2198)));
	}

	// --- the cone does not move with you ---

	@Test
	public void theConeIsIdenticalFromAllThreeTilesOfASide()
	{
		CaptureZone fromCentre = zone(PitSide.EAST, tile(2574, 2195));
		CaptureZone fromNorth = zone(PitSide.EAST, tile(2574, 2196));
		CaptureZone fromSouth = zone(PitSide.EAST, tile(2574, 2194));

		for (int x = 2560; x <= 2570; x++)
		{
			for (int y = 2185; y <= 2205; y++)
			{
				WorldPoint target = tile(x, y);
				boolean expected = fromCentre.contains(target);

				assertEquals("north tile differs at " + x + "," + y, expected, fromNorth.contains(target));
				assertEquals("south tile differs at " + x + "," + y, expected, fromSouth.contains(target));
			}
		}
	}

	@Test
	public void standingOffCentreDoesNotTiltTheCone()
	{
		// From the north-east tile the cone still straddles the pit's centre row, so it
		// reaches equally far north and south of y=2195.
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2196));

		assertTrue(zone.contains(tile(2569, 2193)));
		assertTrue(zone.contains(tile(2569, 2197)));
		assertFalse(zone.contains(tile(2569, 2198)));
	}

	// --- each side aims across the pit ---

	@Test
	public void standingWestAimsEast()
	{
		CaptureZone zone = zone(PitSide.WEST, tile(2570, 2195));

		assertTrue(zone.contains(tile(2574, 2195)));
		assertTrue(zone.contains(tile(2575, 2197)));
		assertFalse(zone.contains(tile(2575, 2198)));
		assertFalse(zone.contains(tile(2570, 2195)));
	}

	@Test
	public void standingNorthAimsSouthAndWidensTwiceAsFast()
	{
		// The pit's south edge is y=2194, so y=2193 is d=1 and the spread of 2 admits
		// offsets up to 2 from the pit's centre column.
		CaptureZone zone = zone(PitSide.NORTH, tile(2572, 2197));

		assertTrue(zone.contains(tile(2572, 2193)));
		assertTrue(zone.contains(tile(2574, 2193)));
		assertTrue(zone.contains(tile(2570, 2193)));
		assertFalse(zone.contains(tile(2575, 2193)));

		assertTrue(zone.contains(tile(2576, 2192)));
		assertFalse(zone.contains(tile(2577, 2192)));
	}

	@Test
	public void standingSouthAimsNorth()
	{
		CaptureZone zone = zone(PitSide.SOUTH, tile(2572, 2193));

		assertTrue(zone.contains(tile(2572, 2197)));
		assertTrue(zone.contains(tile(2574, 2197)));
		assertFalse(zone.contains(tile(2575, 2197)));
		assertFalse(zone.contains(tile(2572, 2193)));
	}

	// --- range is measured from you, because telegrab is cast from you ---

	@Test
	public void rangeIsCappedFromThePlayerNotThePit()
	{
		WorldPoint standing = tile(2574, 2195);
		CaptureZone zone = new CaptureZone(PIT, PitSide.EAST, standing, EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, 10);

		// x=2564 is exactly 10 tiles from the player.
		assertTrue(zone.contains(tile(2564, 2195)));
		assertFalse(zone.contains(tile(2563, 2195)));
	}

	@Test
	public void tilesOnAnotherPlaneAreNeverInTheZone()
	{
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));
		assertFalse(zone.contains(new WorldPoint(2570, 2195, 1)));
	}

	// --- enumeration, used to paint the cone on the ground ---

	@Test
	public void tilesEnumeratesExactlyWhatTheZoneContains()
	{
		CaptureZone zone = new CaptureZone(PIT, PitSide.NORTH, tile(2572, 2197), EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, 8);

		List<WorldPoint> tiles = zone.tiles();
		for (WorldPoint t : tiles)
		{
			assertTrue("enumerated tile must be contained: " + t, zone.contains(t));
		}

		assertEquals("no duplicates", tiles.size(), new HashSet<>(tiles).size());
	}

	@Test
	public void tilesRespectsTheRangeCap()
	{
		WorldPoint standing = tile(2574, 2195);

		// The player sits 3 tiles outside the cone's first row (2 to the pit centre, 1
		// more to its edge), so a range of 4 admits only d = 1: three tiles.
		CaptureZone tight = new CaptureZone(PIT, PitSide.EAST, standing, EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, 4);
		assertEquals(3, tight.tiles().size());

		// A range of 5 adds d = 2, which is five tiles wide.
		CaptureZone looser = new CaptureZone(PIT, PitSide.EAST, standing, EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, 5);
		assertEquals(8, looser.tiles().size());
	}

	@Test
	public void tilesAreEnumeratedOnceAndKept()
	{
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));

		assertSame("the overlay asks every frame, so the walk must not repeat", zone.tiles(), zone.tiles());
	}

	// --- reuse, so a zone that has not changed keeps its enumerated tiles ---

	@Test
	public void aZoneMatchesTheSameSideTileAndWidth()
	{
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));

		assertTrue(zone.matches(PitSide.EAST, tile(2574, 2195), ConeWidth.QUARTER));
	}

	@Test
	public void aZoneDoesNotMatchADifferentSideTileOrWidth()
	{
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));

		assertFalse("a different side aims elsewhere", zone.matches(PitSide.NORTH, tile(2574, 2195), ConeWidth.QUARTER));
		assertFalse("a different tile moves the range cap", zone.matches(PitSide.EAST, tile(2574, 2196), ConeWidth.QUARTER));
		assertFalse("a different width is a different shape", zone.matches(PitSide.EAST, tile(2574, 2195), ConeWidth.HALF));
	}

	// --- the widened cone: the entire opposite half ---

	private static CaptureZone half(PitSide side, WorldPoint standing)
	{
		return new CaptureZone(PIT, side, standing, EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, GENEROUS_RANGE, ConeWidth.HALF);
	}

	@Test
	public void theWidenedConeTakesEverythingPastThePit()
	{
		CaptureZone zone = half(PitSide.EAST, tile(2574, 2195));

		// Far off the centre line, which the quartered cone would reject at this distance.
		assertTrue(zone.contains(tile(2570, 2205)));
		assertTrue(zone.contains(tile(2570, 2185)));
		assertTrue(zone.contains(tile(2560, 2210)));
	}

	@Test
	public void theWidenedConeStillStartsPastThePitsEdge()
	{
		CaptureZone zone = half(PitSide.EAST, tile(2574, 2195));

		for (int y = 2185; y <= 2205; y++)
		{
			assertFalse("pit column must stay out at y=" + y, zone.contains(tile(2572, y)));
		}

		// Nothing on your own half is capturable, however far off the centre line.
		assertFalse(zone.contains(tile(2575, 2205)));
		assertFalse(zone.contains(tile(2574, 2185)));
	}

	@Test
	public void theWidenedConeIsStillCappedByRange()
	{
		WorldPoint standing = tile(2574, 2195);
		CaptureZone zone = new CaptureZone(PIT, PitSide.EAST, standing, EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, 10, ConeWidth.HALF);

		assertTrue(zone.contains(tile(2570, 2205)));
		assertFalse(zone.contains(tile(2570, 2206)));
	}

	@Test
	public void widenedNorthAndSouthSplitTheOtherAxis()
	{
		CaptureZone zone = half(PitSide.NORTH, tile(2572, 2197));

		assertTrue(zone.contains(tile(2560, 2193)));
		assertTrue(zone.contains(tile(2585, 2193)));
		assertFalse("your own half stays out", zone.contains(tile(2560, 2197)));
	}

	@Test
	public void theWidenedConeIsASupersetOfTheQuarteredOne()
	{
		WorldPoint standing = tile(2574, 2195);
		CaptureZone quarter = zone(PitSide.EAST, standing);
		CaptureZone widened = half(PitSide.EAST, standing);

		for (int x = 2555; x <= 2580; x++)
		{
			for (int y = 2180; y <= 2210; y++)
			{
				WorldPoint target = tile(x, y);
				if (quarter.contains(target))
				{
					assertTrue("widening must never drop a tile: " + target, widened.contains(target));
				}
			}
		}
	}

	@Test
	public void theDefaultConstructorStaysQuartered()
	{
		CaptureZone zone = zone(PitSide.EAST, tile(2574, 2195));

		assertFalse(zone.contains(tile(2570, 2205)));
	}

	@Test
	public void tilesEnumeratesTheWidenedConeToo()
	{
		CaptureZone zone = new CaptureZone(PIT, PitSide.EAST, tile(2574, 2195), EAST_WEST_SPREAD, NORTH_SOUTH_SPREAD, 6, ConeWidth.HALF);

		List<WorldPoint> tiles = zone.tiles();
		for (WorldPoint t : tiles)
		{
			assertTrue("enumerated tile must be contained: " + t, zone.contains(t));
		}

		assertEquals("no duplicates", tiles.size(), new HashSet<>(tiles).size());
		assertTrue("should reach well off the centre line", tiles.contains(tile(2570, 2199)));
	}

	// --- the spreads stay independent ---

	@Test
	public void wideningTheEastWestSpreadDoesNotAffectNorthSouth()
	{
		CaptureZone wideEastWest = new CaptureZone(PIT, PitSide.EAST, tile(2574, 2195), 3, NORTH_SOUTH_SPREAD, GENEROUS_RANGE);
		assertTrue(wideEastWest.contains(tile(2570, 2198)));
		assertFalse(wideEastWest.contains(tile(2570, 2199)));

		CaptureZone northUnchanged = new CaptureZone(PIT, PitSide.NORTH, tile(2572, 2197), 3, NORTH_SOUTH_SPREAD, GENEROUS_RANGE);
		assertTrue(northUnchanged.contains(tile(2574, 2193)));
		assertFalse(northUnchanged.contains(tile(2575, 2193)));
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Only a player perpendicular to you competes for the same goats. Someone opposite is
 * aiming at the half you are standing in, so they take nothing you would have taken.
 */
public class ConeWidthTest
{
	@Test
	public void aloneAtThePitYouGetTheWholeOppositeHalf()
	{
		assertEquals(ConeWidth.HALF, ConeWidth.forNeighbours(PitSide.EAST, Collections.emptySet()));
	}

	@Test
	public void aPlayerOppositeDoesNotNarrowYou()
	{
		// They aim east, you aim west. The two never overlap.
		assertEquals(ConeWidth.HALF, ConeWidth.forNeighbours(PitSide.EAST, Collections.singleton(PitSide.WEST)));
		assertEquals(ConeWidth.HALF, ConeWidth.forNeighbours(PitSide.NORTH, Collections.singleton(PitSide.SOUTH)));
	}

	@Test
	public void anotherPlayerOnYourOwnSideDoesNotNarrowYou()
	{
		assertEquals(ConeWidth.HALF, ConeWidth.forNeighbours(PitSide.EAST, Collections.singleton(PitSide.EAST)));
	}

	@Test
	public void aPlayerToYourLeftOrRightQuartersYou()
	{
		assertEquals(ConeWidth.QUARTER, ConeWidth.forNeighbours(PitSide.EAST, Collections.singleton(PitSide.NORTH)));
		assertEquals(ConeWidth.QUARTER, ConeWidth.forNeighbours(PitSide.EAST, Collections.singleton(PitSide.SOUTH)));
		assertEquals(ConeWidth.QUARTER, ConeWidth.forNeighbours(PitSide.NORTH, Collections.singleton(PitSide.EAST)));
		assertEquals(ConeWidth.QUARTER, ConeWidth.forNeighbours(PitSide.NORTH, Collections.singleton(PitSide.WEST)));
	}

	@Test
	public void oneperpendicularPlayerIsEnoughEvenAlongsideAnOppositeOne()
	{
		assertEquals(ConeWidth.QUARTER,
			ConeWidth.forNeighbours(PitSide.EAST, Arrays.asList(PitSide.WEST, PitSide.NORTH)));
	}

	@Test
	public void aFullHouseQuartersEveryone()
	{
		for (PitSide mine : PitSide.values())
		{
			assertEquals(ConeWidth.QUARTER,
				ConeWidth.forNeighbours(mine, Arrays.asList(PitSide.NORTH, PitSide.SOUTH, PitSide.EAST, PitSide.WEST)));
		}
	}

	@Test
	public void everySideWidensWhenOnlyItsOppositeIsTaken()
	{
		assertEquals(ConeWidth.HALF, ConeWidth.forNeighbours(PitSide.WEST, Collections.singleton(PitSide.EAST)));
		assertEquals(ConeWidth.HALF, ConeWidth.forNeighbours(PitSide.SOUTH, Collections.singleton(PitSide.NORTH)));
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Adjacency decides whether the goat's "Prod" option is left as the default left-click.
 * Up close it is what you want; at range it walks you over.
 */
public class GoatPitTest
{
	private static final WorldPoint PLAYER = new WorldPoint(2574, 2195, 0);

	private static WorldPoint tile(int x, int y, int plane)
	{
		return new WorldPoint(x, y, plane);
	}

	@Test
	public void theSameTileCountsAsAdjacent()
	{
		assertTrue(GoatPit.isAdjacent(PLAYER, tile(2574, 2195, 0)));
	}

	@Test
	public void orthogonalNeighboursAreAdjacent()
	{
		assertTrue(GoatPit.isAdjacent(PLAYER, tile(2575, 2195, 0)));
		assertTrue(GoatPit.isAdjacent(PLAYER, tile(2573, 2195, 0)));
		assertTrue(GoatPit.isAdjacent(PLAYER, tile(2574, 2196, 0)));
		assertTrue(GoatPit.isAdjacent(PLAYER, tile(2574, 2194, 0)));
	}

	@Test
	public void diagonalNeighboursAreAdjacent()
	{
		assertTrue(GoatPit.isAdjacent(PLAYER, tile(2575, 2196, 0)));
		assertTrue(GoatPit.isAdjacent(PLAYER, tile(2573, 2194, 0)));
	}

	@Test
	public void twoTilesAwayIsNotAdjacent()
	{
		assertFalse(GoatPit.isAdjacent(PLAYER, tile(2576, 2195, 0)));
		assertFalse(GoatPit.isAdjacent(PLAYER, tile(2574, 2197, 0)));
		assertFalse(GoatPit.isAdjacent(PLAYER, tile(2576, 2197, 0)));
	}

	@Test
	public void anotherPlaneIsNeverAdjacent()
	{
		assertFalse(GoatPit.isAdjacent(PLAYER, tile(2574, 2195, 1)));
	}

	@Test
	public void nullsAreNotAdjacent()
	{
		assertFalse(GoatPit.isAdjacent(null, tile(2574, 2195, 0)));
		assertFalse(GoatPit.isAdjacent(PLAYER, null));
	}

	@Test
	public void theContestedMessageMatchesWhatTheGameSays()
	{
		assertTrue("Someone else is currently moving that goat!".contains(GoatPit.CONTESTED_GOAT_MESSAGE));
	}

	// --- a prod that never happened ---

	@Test
	public void bothCattleprodRefusalsAreRecognised()
	{
		assertTrue(GoatPit.isFailedProdMessage(
			"You don't think your current weapon would work as a cattleprod."));
		assertTrue(GoatPit.isFailedProdMessage(
			"You should use a cattleprod if you want to prod the goats."));
	}

	@Test
	public void theContestedMessageIsNotAFailedProd()
	{
		// Contested means someone else has the goat; refused means nothing happened at all.
		assertFalse(GoatPit.isFailedProdMessage("Someone else is currently moving that goat!"));
	}

	@Test
	public void mentioningACattleprodIsNotEnoughToCountAsARefusal()
	{
		// Matching on the bare word would cancel a capture that actually succeeded, so the
		// distinctive half of each refusal is what we look for.
		assertFalse(GoatPit.isFailedProdMessage("You prod the goat with your cattleprod."));
		assertFalse(GoatPit.isFailedProdMessage("You equip your cattleprod."));
	}

	@Test
	public void ordinaryChatIsNotAFailedProd()
	{
		assertFalse(GoatPit.isFailedProdMessage("You prod the goat towards the pit."));
		assertFalse(GoatPit.isFailedProdMessage("Oh dear, you are dead!"));
		assertFalse(GoatPit.isFailedProdMessage(""));
		assertFalse(GoatPit.isFailedProdMessage(null));
	}

	// --- the activity gate: nothing runs unless you are near the pit ---

	@Test
	public void standingAtThePitIsInRange()
	{
		assertTrue(GoatPit.isNearPit(GoatPit.PIT_LOCATION));
		assertTrue(GoatPit.isNearPit(tile(2574, 2195, 0)));
	}

	@Test
	public void theEdgeOfTheRangeIsIncluded()
	{
		int r = GoatPit.ACTIVITY_RADIUS;

		assertTrue(GoatPit.isNearPit(tile(2572 + r, 2195, 0)));
		assertTrue(GoatPit.isNearPit(tile(2572 - r, 2195, 0)));
		assertTrue(GoatPit.isNearPit(tile(2572, 2195 + r, 0)));
		assertTrue(GoatPit.isNearPit(tile(2572, 2195 - r, 0)));
	}

	@Test
	public void oneTilePastTheRangeIsOut()
	{
		int r = GoatPit.ACTIVITY_RADIUS + 1;

		assertFalse(GoatPit.isNearPit(tile(2572 + r, 2195, 0)));
		assertFalse(GoatPit.isNearPit(tile(2572, 2195 - r, 0)));
	}

	@Test
	public void rangeIsMeasuredOnBothAxesAtOnce()
	{
		int r = GoatPit.ACTIVITY_RADIUS;

		// Chebyshev: out to the full radius on both axes at once is still within range.
		assertTrue(GoatPit.isNearPit(tile(2572 + r, 2195 + r, 0)));
		assertFalse(GoatPit.isNearPit(tile(2572 + r + 1, 2195 + r, 0)));
	}

	@Test
	public void theRadiusCoversEverythingACaptureCanReach()
	{
		// You stand STANDING_DISTANCE from the centre and telegrab reaches TELEGRAB_RANGE
		// past that, so the gate must not cut off inside a goat you could actually take.
		assertTrue("radius must cover the whole capture envelope",
			GoatPit.ACTIVITY_RADIUS >= GoatPit.STANDING_DISTANCE + GoatPit.TELEGRAB_RANGE);
	}

	@Test
	public void anotherPlaneIsNeverInRange()
	{
		assertFalse(GoatPit.isNearPit(new WorldPoint(2572, 2195, 1)));
	}

	@Test
	public void nowhereIsNotInRange()
	{
		assertFalse(GoatPit.isNearPit(null));
	}

	@Test
	public void somewhereElseEntirelyIsOutOfRange()
	{
		// Lumbridge.
		assertFalse(GoatPit.isNearPit(tile(3222, 3218, 0)));
	}

	// --- the capture sequence: spot anim 144 FIRST, then a pull animation ---

	private static final int IDLE_ANIMATION = -1;
	private static final boolean CLAIMED = true;
	private static final boolean UNCLAIMED = false;

	@Test
	public void anUntouchedGoatIsNotBeingCaptured()
	{
		assertFalse(GoatPit.isBeingCaptured(false, IDLE_ANIMATION, UNCLAIMED));
	}

	@Test
	public void theSpotAnimOpensACaptureOnItsOwn()
	{
		assertTrue(GoatPit.isBeingCaptured(true, IDLE_ANIMATION, UNCLAIMED));
	}

	@Test
	public void aPullAnimationAloneDoesNotOpenACapture()
	{
		// This is the whole point of requiring the sequence: goats animate for reasons
		// that have nothing to do with our pit, and counting those inflated the in-flight
		// total against an empty pit.
		assertFalse(GoatPit.isBeingCaptured(false, GoatPit.ANIMATION_BEING_PULLED, UNCLAIMED));
		assertFalse(GoatPit.isBeingCaptured(false, GoatPit.ANIMATION_BEING_PULLED_ALT, UNCLAIMED));
	}

	@Test
	public void aPullAnimationContinuesACaptureTheSpotAnimAlreadyOpened()
	{
		assertTrue(GoatPit.isBeingCaptured(false, GoatPit.ANIMATION_BEING_PULLED, CLAIMED));
		assertTrue(GoatPit.isBeingCaptured(false, GoatPit.ANIMATION_BEING_PULLED_ALT, CLAIMED));
	}

	@Test
	public void anIdleClaimedGoatIsNotStillBeingPulled()
	{
		// The claim exists but nothing is happening, so let it lapse on its timer.
		assertFalse(GoatPit.isBeingCaptured(false, IDLE_ANIMATION, CLAIMED));
	}

	@Test
	public void anUnrelatedAnimationNeverCounts()
	{
		assertFalse(GoatPit.isBeingCaptured(false, 808, UNCLAIMED));
		assertFalse(GoatPit.isBeingCaptured(false, 808, CLAIMED));
	}

	@Test
	public void theWholeSequenceReadsAsCapturedThroughout()
	{
		// 144 for several ticks, opening the claim...
		assertTrue(GoatPit.isBeingCaptured(true, IDLE_ANIMATION, UNCLAIMED));
		assertTrue(GoatPit.isBeingCaptured(true, IDLE_ANIMATION, CLAIMED));
		// ...then it drops and the pull animation carries it.
		assertTrue(GoatPit.isBeingCaptured(false, GoatPit.ANIMATION_BEING_PULLED, CLAIMED));
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class GoatTargeterTest
{
	private static final WorldPoint PIT = new WorldPoint(2572, 2195, 0);
	private static final WorldPoint STANDING = new WorldPoint(2572, 2197, 0);

	/** Standing on the north-centre tile, so the cone opens south with a spread of 2. */
	private static final CaptureZone ZONE = new CaptureZone(PIT, PitSide.NORTH, STANDING, 1, 2, 12);

	/** A goat you have a clear shot at. */
	private static GoatCandidate goat(int index, int x, int y)
	{
		return new GoatCandidate(index, new WorldPoint(x, y, 0), true);
	}

	/** A goat in the cone but behind something, so telegrabbing it makes you run around. */
	private static GoatCandidate blocked(int index, int x, int y)
	{
		return new GoatCandidate(index, new WorldPoint(x, y, 0), false);
	}

	private static GoatTargeter.Selection select(List<GoatCandidate> goats)
	{
		return GoatTargeter.select(goats, ZONE, Collections.emptySet());
	}

	@Test
	public void everyGoatInTheConeIsCapturable()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(goat(5, 2572, 2193), goat(7, 2572, 2191)));

		assertEquals(new HashSet<>(Arrays.asList(5, 7)), selection.capturable());
	}

	@Test
	public void goatsOutsideTheConeAreNotCapturable()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(goat(5, 2572, 2193), goat(7, 2578, 2193)));

		assertEquals(Collections.singleton(5), selection.capturable());
		assertFalse(selection.isCapturable(7));
	}

	@Test
	public void goatsOnThePitSideOfYouAreNotCapturable()
	{
		GoatTargeter.Selection selection = select(Collections.singletonList(goat(5, 2572, 2199)));

		assertTrue(selection.capturable().isEmpty());
	}

	@Test
	public void theGoatClosestToThePitIsSingledOut()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(
			goat(7, 2572, 2191),
			goat(5, 2572, 2193),
			goat(9, 2572, 2188)));

		assertEquals(Integer.valueOf(5), selection.closestIndex());
		assertTrue(selection.isClosest(5));
		assertFalse(selection.isClosest(7));
	}

	@Test
	public void theClosestGoatIsAlsoCapturable()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(goat(7, 2572, 2191), goat(5, 2572, 2193)));

		assertTrue(selection.isCapturable(selection.closestIndex()));
	}

	@Test
	public void distanceIsMeasuredFromThePitNotFromThePlayer()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(goat(9, 2572, 2192), goat(3, 2576, 2192)));

		assertEquals(Integer.valueOf(9), selection.closestIndex());
	}

	@Test
	public void tiesAreBrokenByLowestIndexSoTheHighlightDoesNotFlicker()
	{
		GoatTargeter.Selection first = select(Arrays.asList(
			goat(9, 2572, 2193),
			goat(3, 2571, 2193),
			goat(6, 2573, 2193)));
		assertEquals(Integer.valueOf(3), first.closestIndex());

		GoatTargeter.Selection second = select(Arrays.asList(
			goat(6, 2573, 2193),
			goat(9, 2572, 2193),
			goat(3, 2571, 2193)));
		assertEquals(Integer.valueOf(3), second.closestIndex());
	}

	@Test
	public void withNoGoatsInRangeThereIsNoClosest()
	{
		GoatTargeter.Selection selection = select(Collections.singletonList(goat(5, 2578, 2193)));

		assertNull(selection.closestIndex());
		assertTrue(selection.capturable().isEmpty());
		assertFalse(selection.isClosest(5));
	}

	@Test
	public void suppressedGoatsAreExcludedEntirely()
	{
		List<GoatCandidate> goats = Arrays.asList(goat(5, 2572, 2193), goat(7, 2572, 2191));

		GoatTargeter.Selection selection = GoatTargeter.select(goats, ZONE, Collections.singleton(5));

		assertFalse(selection.isCapturable(5));
		assertFalse(selection.isBlocked(5));
		assertFalse(selection.isClosest(5));
		assertEquals(Collections.singleton(7), selection.capturable());
	}

	@Test
	public void suppressingTheClosestGoatPromotesTheNextOne()
	{
		List<GoatCandidate> goats = Arrays.asList(
			goat(5, 2572, 2193),
			goat(7, 2572, 2191),
			goat(9, 2572, 2188));

		GoatTargeter.Selection selection = GoatTargeter.select(goats, ZONE, Collections.singleton(5));

		assertEquals(Integer.valueOf(7), selection.closestIndex());
	}

	@Test
	public void isClosestIsFalseWhenNothingIsSelected()
	{
		GoatTargeter.Selection selection = select(Collections.emptyList());

		assertNull(selection.closestIndex());
		assertFalse(selection.isClosest(0));
	}

	// --- line of sight ---

	@Test
	public void aBlockedGoatIsReportedSeparatelyFromACapturableOne()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(goat(5, 2572, 2191), blocked(7, 2572, 2193)));

		assertEquals(Collections.singleton(5), selection.capturable());
		assertEquals(Collections.singleton(7), selection.blocked());
		assertTrue(selection.isBlocked(7));
		assertFalse(selection.isCapturable(7));
	}

	@Test
	public void aBlockedGoatIsNeverRecommendedEvenWhenItIsNearest()
	{
		// Index 7 is one tile past the pit and index 5 is three, but 7 is behind cover.
		GoatTargeter.Selection selection = select(Arrays.asList(blocked(7, 2572, 2193), goat(5, 2572, 2191)));

		assertEquals(Integer.valueOf(5), selection.closestIndex());
		assertFalse(selection.isClosest(7));
	}

	@Test
	public void withOnlyBlockedGoatsThereIsNoRecommendation()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(blocked(5, 2572, 2193), blocked(7, 2572, 2191)));

		assertNull(selection.closestIndex());
		assertEquals(new HashSet<>(Arrays.asList(5, 7)), selection.blocked());
		assertTrue(selection.capturable().isEmpty());
	}

	@Test
	public void blockedGoatsOutsideTheConeAreNotReportedAtAll()
	{
		GoatTargeter.Selection selection = select(Collections.singletonList(blocked(5, 2578, 2193)));

		assertTrue(selection.blocked().isEmpty());
		assertTrue(selection.capturable().isEmpty());
	}

	@Test
	public void aSuppressedBlockedGoatIsNotReportedEither()
	{
		List<GoatCandidate> goats = Collections.singletonList(blocked(5, 2572, 2193));

		GoatTargeter.Selection selection = GoatTargeter.select(goats, ZONE, Collections.singleton(5));

		assertTrue(selection.blocked().isEmpty());
	}

	@Test
	public void capturableAndBlockedNeverOverlap()
	{
		GoatTargeter.Selection selection = select(Arrays.asList(
			goat(1, 2572, 2193),
			blocked(2, 2571, 2193),
			goat(3, 2572, 2191),
			blocked(4, 2573, 2192)));

		HashSet<Integer> intersection = new HashSet<>(selection.capturable());
		intersection.retainAll(selection.blocked());

		assertTrue("a goat cannot be both capturable and blocked", intersection.isEmpty());
	}

	// --- nothing to draw, so the overlay can skip the scene entirely ---

	@Test
	public void aSelectionWithNothingInItIsEmpty()
	{
		assertTrue(GoatTargeter.Selection.empty().isEmpty());
		assertTrue(select(Collections.singletonList(goat(5, 2578, 2193))).isEmpty());
	}

	@Test
	public void aSelectionHoldingAnyGoatIsNotEmpty()
	{
		assertFalse(select(Collections.singletonList(goat(5, 2572, 2193))).isEmpty());
		assertFalse("a blocked goat is still drawn", select(Collections.singletonList(blocked(7, 2572, 2193))).isEmpty());
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The fractions behind the bar drawn over the pit. Goats already on their way show as a
 * second, fainter segment, so the bar reads as how full the pit is about to be.
 */
public class PitFillTest
{
	private static final double DELTA = 0.0001;

	@Test
	public void anEmptyPitIsEmpty()
	{
		PitFill fill = PitFill.of(0, 0);

		assertEquals(0.0, fill.landed(), DELTA);
		assertEquals(0.0, fill.pending(), DELTA);
		assertEquals(0.0, fill.total(), DELTA);
		assertTrue(fill.isEmpty());
	}

	@Test
	public void landedGoatsFillProportionally()
	{
		assertEquals(0.5, PitFill.of(10, 0).landed(), DELTA);
		assertEquals(0.25, PitFill.of(5, 0).landed(), DELTA);
		assertEquals(1.0, PitFill.of(20, 0).landed(), DELTA);
	}

	@Test
	public void goatsInFlightAddASecondSegment()
	{
		PitFill fill = PitFill.of(16, 3);

		assertEquals(0.8, fill.landed(), DELTA);
		assertEquals(0.15, fill.pending(), DELTA);
		assertEquals(0.95, fill.total(), DELTA);
	}

	@Test
	public void aPitWithOnlyGoatsInFlightShowsOnlyTheFaintSegment()
	{
		PitFill fill = PitFill.of(0, 4);

		assertEquals(0.0, fill.landed(), DELTA);
		assertEquals(0.2, fill.pending(), DELTA);
		assertFalse(fill.isEmpty());
	}

	@Test
	public void theBarNeverOverflows()
	{
		// More in flight than there is room for: the bar tops out rather than running on.
		PitFill fill = PitFill.of(19, 5);

		assertEquals(0.95, fill.landed(), DELTA);
		assertEquals("only the last slot is left to fill", 0.05, fill.pending(), DELTA);
		assertEquals(1.0, fill.total(), DELTA);
	}

	@Test
	public void aFullPitLeavesNoRoomForPending()
	{
		PitFill fill = PitFill.of(20, 3);

		assertEquals(1.0, fill.landed(), DELTA);
		assertEquals(0.0, fill.pending(), DELTA);
		assertEquals(1.0, fill.total(), DELTA);
	}

	@Test
	public void countsBeyondTheMaximumAreClamped()
	{
		assertEquals(1.0, PitFill.of(25, 0).landed(), DELTA);
		assertEquals(1.0, PitFill.of(25, 5).total(), DELTA);
	}

	@Test
	public void negativeCountsAreTreatedAsEmpty()
	{
		PitFill fill = PitFill.of(-1, -1);

		assertEquals(0.0, fill.landed(), DELTA);
		assertEquals(0.0, fill.pending(), DELTA);
		assertTrue(fill.isEmpty());
	}

	@Test
	public void totalIsAlwaysLandedPlusPending()
	{
		for (int inPit = 0; inPit <= GoatPit.MAX_IN_PIT + 3; inPit++)
		{
			for (int inFlight = 0; inFlight <= 6; inFlight++)
			{
				PitFill fill = PitFill.of(inPit, inFlight);

				assertEquals(fill.landed() + fill.pending(), fill.total(), DELTA);
				assertTrue("never above 1: " + inPit + "+" + inFlight, fill.total() <= 1.0 + DELTA);
				assertTrue("never below 0", fill.total() >= 0.0);
			}
		}
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The pit is a 3x3 object centred on {@link GoatPit#PIT_LOCATION}, covering 2571-2573 by
 * 2194-2196. You stand on the ring around it, three tiles per side, corners excluded.
 */
public class PitSideTest
{
	private static final WorldPoint PIT = new WorldPoint(2572, 2195, 0);

	private static WorldPoint tile(int x, int y)
	{
		return new WorldPoint(x, y, 0);
	}

	@Test
	public void recognisesAllThreeEastTiles()
	{
		assertEquals(PitSide.EAST, PitSide.fromStandingTile(PIT, tile(2574, 2194)));
		assertEquals(PitSide.EAST, PitSide.fromStandingTile(PIT, tile(2574, 2195)));
		assertEquals(PitSide.EAST, PitSide.fromStandingTile(PIT, tile(2574, 2196)));
	}

	@Test
	public void recognisesAllThreeNorthTiles()
	{
		assertEquals(PitSide.NORTH, PitSide.fromStandingTile(PIT, tile(2571, 2197)));
		assertEquals(PitSide.NORTH, PitSide.fromStandingTile(PIT, tile(2572, 2197)));
		assertEquals(PitSide.NORTH, PitSide.fromStandingTile(PIT, tile(2573, 2197)));
	}

	@Test
	public void recognisesAllThreeWestTiles()
	{
		assertEquals(PitSide.WEST, PitSide.fromStandingTile(PIT, tile(2570, 2194)));
		assertEquals(PitSide.WEST, PitSide.fromStandingTile(PIT, tile(2570, 2195)));
		assertEquals(PitSide.WEST, PitSide.fromStandingTile(PIT, tile(2570, 2196)));
	}

	@Test
	public void recognisesAllThreeSouthTiles()
	{
		assertEquals(PitSide.SOUTH, PitSide.fromStandingTile(PIT, tile(2571, 2193)));
		assertEquals(PitSide.SOUTH, PitSide.fromStandingTile(PIT, tile(2572, 2193)));
		assertEquals(PitSide.SOUTH, PitSide.fromStandingTile(PIT, tile(2573, 2193)));
	}

	@Test
	public void theFourCornersAreDead()
	{
		assertNull(PitSide.fromStandingTile(PIT, tile(2574, 2197)));
		assertNull(PitSide.fromStandingTile(PIT, tile(2570, 2197)));
		assertNull(PitSide.fromStandingTile(PIT, tile(2574, 2193)));
		assertNull(PitSide.fromStandingTile(PIT, tile(2570, 2193)));
	}

	@Test
	public void tilesOnThePitItselfAreNotStandingTiles()
	{
		assertNull(PitSide.fromStandingTile(PIT, PIT));
		assertNull(PitSide.fromStandingTile(PIT, tile(2571, 2194)));
		assertNull(PitSide.fromStandingTile(PIT, tile(2573, 2196)));
	}

	@Test
	public void tilesFurtherOutAreNotStandingTiles()
	{
		assertNull(PitSide.fromStandingTile(PIT, tile(2575, 2195)));
		assertNull(PitSide.fromStandingTile(PIT, tile(2572, 2198)));
		assertNull(PitSide.fromStandingTile(PIT, tile(2569, 2195)));
		assertNull(PitSide.fromStandingTile(PIT, tile(2572, 2192)));
	}

	@Test
	public void adifferentPlaneIsNotAValidStandingTile()
	{
		assertNull(PitSide.fromStandingTile(PIT, new WorldPoint(2574, 2195, 1)));
	}

	@Test
	public void everyStandingTileIsExactlyTwelve()
	{
		int found = 0;
		for (int x = 2568; x <= 2576; x++)
		{
			for (int y = 2191; y <= 2199; y++)
			{
				if (PitSide.fromStandingTile(PIT, tile(x, y)) != null)
				{
					found++;
				}
			}
		}
		assertEquals(12, found);
	}

	@Test
	public void youAimAtTheOppositeSideOfThePit()
	{
		assertEquals(0, PitSide.NORTH.aimDx());
		assertEquals(-1, PitSide.NORTH.aimDy());

		assertEquals(0, PitSide.SOUTH.aimDx());
		assertEquals(1, PitSide.SOUTH.aimDy());

		assertEquals(-1, PitSide.EAST.aimDx());
		assertEquals(0, PitSide.EAST.aimDy());

		assertEquals(1, PitSide.WEST.aimDx());
		assertEquals(0, PitSide.WEST.aimDy());
	}

	@Test
	public void perpendicularSidesCompeteForTheSameGoats()
	{
		assertTrue(PitSide.EAST.isPerpendicularTo(PitSide.NORTH));
		assertTrue(PitSide.EAST.isPerpendicularTo(PitSide.SOUTH));
		assertTrue(PitSide.NORTH.isPerpendicularTo(PitSide.WEST));
	}

	@Test
	public void yourOwnSideAndTheOppositeOneAreNotPerpendicular()
	{
		assertFalse(PitSide.EAST.isPerpendicularTo(PitSide.EAST));
		assertFalse(PitSide.EAST.isPerpendicularTo(PitSide.WEST));
		assertFalse(PitSide.NORTH.isPerpendicularTo(PitSide.SOUTH));
	}

	@Test
	public void northAndSouthShareTheVerticalAxisEastAndWestTheHorizontalOne()
	{
		assertTrue(PitSide.NORTH.isNorthSouthAxis());
		assertTrue(PitSide.SOUTH.isNorthSouthAxis());
		assertFalse(PitSide.EAST.isNorthSouthAxis());
		assertFalse(PitSide.WEST.isNorthSouthAxis());
	}
}

package com.claudiodekker.wyrmscraiggoathunting;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@code inFlight} is the number of goats already being lured towards the pit. They have
 * not landed yet, so the varbit does not know about them, but they will take slots.
 */
public class PitStatusTest
{
	@Test
	public void emptyAndUnlinedPitNeedsSpikes()
	{
		assertEquals(PitStatus.NEEDS_SPIKES, PitStatus.of(0, 0, 0, 0));
	}

	@Test
	public void liningTheSpikesMakesThePitReady()
	{
		// Lining sets GOAT_PIT_SPIKES 0 -> 1 and GOAT_PIT_STATE 0 -> 1.
		assertEquals(PitStatus.READY, PitStatus.of(1, 1, 0, 0));
	}

	@Test
	public void aPartiallyFullLinedPitIsStillReady()
	{
		assertEquals(PitStatus.READY, PitStatus.of(1, 2, 7, 0));
		assertEquals(PitStatus.READY, PitStatus.of(1, 3, 14, 0));
		assertEquals(PitStatus.READY, PitStatus.of(1, 4, 19, 0));
	}

	@Test
	public void twentyGoatsMakesThePitFull()
	{
		assertEquals(PitStatus.FULL, PitStatus.of(1, 4, 20, 0));
	}

	@Test
	public void removingSpikesFromANonEmptyPitMeansItIsBeingCleared()
	{
		assertEquals(PitStatus.CLEARING, PitStatus.of(0, 4, 20, 0));
		assertEquals(PitStatus.CLEARING, PitStatus.of(0, 1, 3, 0));
	}

	@Test
	public void aClearedPitReturnsToNeedingSpikes()
	{
		assertEquals(PitStatus.NEEDS_SPIKES, PitStatus.of(0, 0, 0, 0));
	}

	// --- in-flight goats reserve the slots they are about to take ---

	@Test
	public void goatsAlreadyOnTheirWayReserveTheLastSlots()
	{
		// 17 landed plus 3 being lured is 20, so casting again would waste the runes.
		assertEquals(PitStatus.RESERVED, PitStatus.of(1, 3, 17, 3));
	}

	@Test
	public void thePitStaysReadyWhileSlotsRemainAfterTheGoatsInFlight()
	{
		assertEquals(PitStatus.READY, PitStatus.of(1, 3, 17, 2));
	}

	@Test
	public void overshootingStillReadsAsReservedRatherThanFull()
	{
		// The pit itself is not full yet, so this needs waiting, not clearing.
		assertEquals(PitStatus.RESERVED, PitStatus.of(1, 4, 19, 5));
	}

	@Test
	public void anActuallyFullPitOutranksAnyReservation()
	{
		// Once 20 have landed the pit needs clearing regardless of what is in flight.
		assertEquals(PitStatus.FULL, PitStatus.of(1, 4, 20, 5));
	}

	@Test
	public void inFlightGoatsDoNotResurrectAPitBeingCleared()
	{
		assertEquals(PitStatus.CLEARING, PitStatus.of(0, 3, 17, 3));
	}

	@Test
	public void inFlightGoatsDoNotAffectAnUnlinedPit()
	{
		assertEquals(PitStatus.NEEDS_SPIKES, PitStatus.of(0, 0, 0, 4));
	}

	// --- whether the pit is holding anything, which is when a fill level means something ---

	@Test
	public void aLinedPitHasAFillLevelWorthShowing()
	{
		assertTrue(PitStatus.READY.isLined());
		assertTrue(PitStatus.RESERVED.isLined());
		assertTrue(PitStatus.FULL.isLined());
	}

	@Test
	public void anUnlinedPitHasNoFillLevelWorthShowing()
	{
		// Nothing is set up, so a bar would only ever read empty.
		assertFalse(PitStatus.NEEDS_SPIKES.isLined());

		// Being emptied out: the spikes are gone and no capture can land.
		assertFalse(PitStatus.CLEARING.isLined());
	}

	@Test
	public void beingLinedTracksTheSpikesVarbit()
	{
		for (int state = 0; state <= 4; state++)
		{
			for (int inPit = 0; inPit <= GoatPit.MAX_IN_PIT; inPit++)
			{
				assertTrue("spikes in, so lined: " + state + "/" + inPit,
					PitStatus.of(1, state, inPit, 0).isLined());
				assertFalse("spikes out, so not lined: " + state + "/" + inPit,
					PitStatus.of(0, state, inPit, 0).isLined());
			}
		}
	}

	// --- only a ready pit is worth casting at ---

	@Test
	public void onlyAReadyPitAllowsCapturing()
	{
		assertTrue(PitStatus.READY.canCapture());
		assertFalse(PitStatus.NEEDS_SPIKES.canCapture());
		assertFalse(PitStatus.RESERVED.canCapture());
		assertFalse(PitStatus.FULL.canCapture());
		assertFalse(PitStatus.CLEARING.canCapture());
	}
}

